import Clipboard from '@react-native-clipboard/clipboard';
import {useNavigation} from '@react-navigation/native';
import {isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import ModalFindRecipient from '../../../document-history/components/ModalFindRecipient';
import Picker from '../shareScreen/components/Picker';
import ModalListOrgPermission from './components/ModalListOrgPermission';
import {handleListMemberCanPermit} from './components/ModalListOrgPermission/helper';
import {LINKING_URL} from './helper';
import styles from './styles';
import {
  IDocument,
  IExternalShared,
  IFinderRecipient,
  IOrg,
} from '../../../../../model/interface/envelope.interface';
import {useDocumentStore} from '../../../../../navigation/SideMenu/store/app-store';
import {ItemType} from '../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import TextCM from '../../../../../components/Text';
import {
  IconBlackSearch,
  IconBlueClose,
  IconGreyCopy,
} from '../../../../../assets/images';
import {DateUtils} from '../../../../../utils';
import ButtonCM from '../../../../../components/Button';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

const PermissionScreen = ({data}: {data: IDocument}) => {
  const [showModal, setShowModal] = useState({
    modalListOrg: false,
    modalFindUser: false,
  });
  const currentFocused = useDocumentStore(state => state.currentFocused);

  const [listOrg, setListOrg] = useState<IOrg[]>([]);

  const [currentOrg, setCurrentOrg] = useState<IOrg | undefined>();

  const [listShared, setListShared] = useState<IExternalShared[]>([]);

  const [listOld, setListOld] = useState<IExternalShared[]>([]);

  const [listNew, setListNew] = useState<any[]>([]);

  const navigation = useNavigation();

  const {t} = useTranslation();

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    getOrganization();
  }, []);

  const getOrganization = async () => {
    try {
      const res = await DocumentServices.getFindOrganization();
      const resOrg = await getData(res[0]);
      setListOrg(res);
      setCurrentOrg(res[0]);
    } catch (error) {}
  };

  const getData = async (itemSelected: any) => {
    try {
      const [resGroupsBelongOrg, resUser, resGroup] = await Promise.all([
        // get toan bo group cua to chuc
        DocumentServices.getGroupBelongOrg(itemSelected?.orgIn),
        // get toan bo user cua to chuc
        DocumentServices.getUserNoSig({
          activated: itemSelected?.activated,
          blocked: itemSelected?.blocked,
          orgIn: itemSelected?.orgIn,
        }),
        // get toan bo group va person da phan quyen cua tai lieu
        DocumentServices.getGroupAclInternal(data.id),
      ]);
      const listUser = handleListMemberCanPermit({
        organiztion: itemSelected,
        dataEnvelope: data,
        listUserInOrg: resUser ?? [],
        listGroupInOrg: resGroupsBelongOrg,
        listAllGroupAndPersonShareBelongtoEnvelop: resGroup,
      });
      setListShared(listUser.listShared);
    } catch (error) {}
  };

  const onSubmit = async () => {
    try {
      const res = await DocumentServices.editAclInternal({
        listNew: listNew,
        listOld: listOld,
      });
      Toast.show({
        type: 'success',
        text1:
          currentFocused === ItemType.MyDocumentTemplate
            ? t('eContract.DC.ShareTheDocumentTemplateSuccessfully', {name: data.name})
            : t('eContract.DC.ShareDocument.updatePermission', {name: data.name}),
      });
    } catch (error) {
    } finally {
      navigation.goBack();
    }
  };

  const toggleModal = (modalName: string) => () => {
    switch (modalName) {
      case 'modalListOrg':
        setShowModal({...showModal, modalListOrg: !showModal.modalListOrg});
        break;
      case 'modalFindUser':
        setShowModal({
          ...showModal,
          modalFindUser: !showModal.modalFindUser,
        });
        break;
      default:
        break;
    }
  };

  const onPressCopy = async () => {
    try {
      await Clipboard.setString(`${LINKING_URL}${data.id}`);
      Toast.show({
        type: 'success',
        text1: t('eContract.DC.ShareDocument.hasCopyLink'),
      });
    } catch (error) {}
  };

  const handleOnpressFromModalPermission = (data: any, orgSelected: IOrg) => {
    setCurrentOrg(orgSelected);
    getData(orgSelected);
    setListNew(data);
  };

  const onRemoveShared = (item: any) => () => {
    if (item?.id) {
      setListShared(listShared.filter(i => i.group !== item.group));
      setListOld(prev => [...prev, item]);
    } else {
      setListNew(listNew.filter(i => i.group !== item.group));
    }
  };

  const handleOnpress = async (user: IFinderRecipient) => {
    try {
      setListShared([]);
      setCurrentOrg(listOrg.find(i => i.orgIn.includes(user.orgIn)));
      const res = await DocumentServices.getUserNoSig({
        activated: true,
        blocked: false,
        orgIn: user.orgIn,
      });
      const userFinder = res.find((i: any) => i.login === user.email);
      setListNew(
        currentFocused === ItemType.MyDocumentTemplate
          ? [
              {
                id: null,
                resourceId: data.id,
                resourceName: data.name,
                resourceType: 't',
                sharedType: 'p',
                personal: userFinder?.email,
                group: userFinder?.id,
                password: null,
                perm: 'r',
                fromDate: new Date().toISOString(),
                toDate: null,
                custId: userFinder?.custId,
                orgIn: userFinder?.orgIn,
                activityLogName: userFinder?.email,
              },
            ]
          : [
              {
                id: null,
                resourceId: data.id,
                resourceName: data.name,
                resourceType: 'e',
                sharedType: 'p',
                personal: userFinder?.email,
                group: userFinder?.id,
                password: null,
                perm: 'v_d',
                fromDate: new Date().toISOString(),
                toDate: null,
                custId: userFinder?.custId,
                orgIn: userFinder?.orgIn,
                activityLogName: userFinder?.email,
              },
            ],
      );
    } catch (error) {}
  };

  const renderListShare = () => {
    return (
      <View style={styles.ctnShareView}>
        <TextCM style={styles.txtLabel16}>
          {t('eContract.DC.ShareDocument.memberShared')}
        </TextCM>
        <ScrollView style={styles.ctnSharedList}>
          <View style={styles.ctnViewShared}>
            {isEmpty(listShared) && isEmpty(listNew) && (
              <TextCM style={styles.txtNodata}>
                {t('eContract.DC.ShareDocument.listEmpty')}
              </TextCM>
            )}
            {[...listShared, ...listNew].map((item, index) => {
              return (
                <View style={styles.viewItemHashtag} key={index}>
                  <TextCM style={styles.txtHashtag}>{`(${
                    item?.personal ?? ''
                  })`}</TextCM>
                  <TouchableOpacity onPress={onRemoveShared(item)}>
                    <IconBlueClose width={12} height={12} />
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        </ScrollView>
      </View>
    );
  };
  // list external shared

  return (
    <View style={styles.ctnMain}>
      <View style={styles.ctnScrollMain}>
        <View style={styles.ctnView}>
          {currentFocused !== ItemType.MyDocumentTemplate ? (
            <>
              <TextCM style={styles.txtTitle}>
                {t('eContract.DC.ShareDocument.label')}
              </TextCM>
              <TextCM style={styles.txtNameDocument}>{data?.name}</TextCM>
            </>
          ) : (
            <>
              <TextCM style={styles.txtTitleDocumentTemplate}>
                {t('eContract.DC.ShareDocument.label')}
              </TextCM>
              <View style={styles.viewItem}>
                <TextCM style={styles.txtName}>
                  {t('eContract.DC.TxtNameDocument')}
                </TextCM>
                <TextCM style={styles.txtValue}>{data?.name}</TextCM>
              </View>
            </>
          )}
          <View style={styles.groupTextField}>
            {currentFocused === ItemType.MyDocumentTemplate && (
              <>
                <View style={styles.viewItem}>
                  <TextCM style={styles.txtName}>
                    {t('eContract.DC.TxtCreateDate')}
                  </TextCM>
                  <TextCM style={styles.txtValue}>
                    {DateUtils.convertDateToDDMMYYYY(data?.createdDate)}
                  </TextCM>
                </View>
                <View style={styles.viewItem}>
                  <View style={styles.viewName}>
                    <TextCM style={styles.txtName}>{t('eContract.DC.TxtParties')}</TextCM>
                  </View>
                  <View style={styles.viewValueParties}>
                    {!isEmpty(data?.parties) ? (
                      data?.parties?.map((item: any) => {
                        return (
                          <TextCM style={styles.txtValue} key={item.id}>
                            {item.type !== 'individual'
                              ? item.name || '---'
                              : item.recipients?.[0]?.contact?.name}
                          </TextCM>
                        );
                      })
                    ) : (
                      <TextCM style={styles.txtValue}>---</TextCM>
                    )}
                  </View>
                </View>
              </>
            )}
            {currentFocused !== ItemType.MyDocumentTemplate && (
              <Picker
                type="inactive"
                value={`${LINKING_URL}${data.id}`}
                label={t('eContract.DC.ShareDocument.urlLink')}
                onPress={onPressCopy}
                viewIconRight={
                  <View style={{marginLeft: 12}}>
                    <IconGreyCopy width={24} height={24} />
                  </View>
                }
              />
            )}
            <Picker
              label={t('eContract.DC.typeInfoUser')}
              onPress={toggleModal('modalFindUser')}
              styleInput={{color: '#667085'}}
              viewIconRight={<IconBlackSearch width={24} height={24} />}
            />
            <Picker
              value={currentOrg?.name}
              label={t('eContract.AI.TxtUnit')}
              onPress={toggleModal('modalListOrg')}
            />
          </View>
        </View>
        {renderListShare()}
      </View>
      <View>
        <ButtonCM
          disabled={isEmpty(listOld) && isEmpty(listNew)}
          label={t('eContract.DC.TxtSaveChange')}
          onPress={onSubmit}
          style={{marginHorizontal: 16, marginBottom: 16}}
        />
      </View>
      {showModal.modalListOrg && (
        <ModalListOrgPermission
          onClose={toggleModal('modalListOrg')}
          isVisible={showModal.modalListOrg}
          data={listOrg}
          onPress={handleOnpressFromModalPermission}
          dataEnvelope={data}
        />
      )}
      {showModal.modalFindUser && (
        <ModalFindRecipient
          styleContainer={{backgroundColor: '#000810B2'}}
          onClose={toggleModal('modalFindUser')}
          isVisible={showModal.modalFindUser}
          onSelected={handleOnpress}
        />
      )}
    </View>
  );
};

export default PermissionScreen;
