import React, {useMemo, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {KeyboardAvoidingView, Modal, TouchableOpacity} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {IConfigPassword, LIST_CONFIG_PASSWORD} from '../../helper';
import CounterItem from '../CounterItem';
import {handleInitialCounter, IAttrs, mappingAttributeTypes} from './helper';
import styles from './styles';
import {IPasswordConfig} from '../../../../../services/interface';
import useCounter from '../../../../../hook/useCounter';
import {View as ViewCM} from 'react-native';
import {
  IcBlackLeftArrow,
  IcCheckbox,
  IcCheckboxSelect,
} from '../../../../../assets/images';
import {SizeDP} from '../../../../../constants/Size';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';

type ModalConfigPasswordProp = {
  onClose: () => void;
  isVisible: boolean;
  data?: IPasswordConfig;
  type?: IConfigPassword;
  onSubmit: (type: IConfigPassword, data: any) => void;
};

const ModalConfigPassword = ({
  data,
  onClose,
  isVisible,
  type,
  onSubmit,
}: ModalConfigPasswordProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();

  const [attribute, setAttribute] = useState<any>(data?.attrs);

  const attributeTypeArr = useMemo(() => {
    return mappingAttributeTypes(type);
  }, [type]);

  const counterArr = useMemo(() => {
    return handleInitialCounter(
      type,
      data?.attrs?.[attributeTypeArr[0]]?.value ?? 0,
      data?.attrs?.[attributeTypeArr[1]]?.value ?? 0,
    );
  }, [data]);

  const [value, increase, decrease, setCountData] = useCounter({
    initialValue: counterArr[0].value ?? 0,
    min: counterArr[0].min,
    max: counterArr[0].max,
  });

  const [valueSecond, increaseSecond, decreaseSecond, setCountDataSecond] =
    useCounter({
      initialValue: counterArr?.[1]?.value ?? 0,
      min: counterArr?.[1]?.min,
      max: counterArr?.[1]?.max,
    });

  const handleOnsubmit = () => {
    if (attributeTypeArr.length > 1) {
      onSubmit(type ?? IConfigPassword.complexPassword, {
        ...data,
        attrs: {
          ...attribute,
          [attributeTypeArr[0]]: {
            ...attribute?.[attributeTypeArr[0]],
            value: value,
          },
          [attributeTypeArr[1]]: {
            ...attribute?.[attributeTypeArr[1]],
            value: valueSecond,
          },
        },
      });
    } else {
      onSubmit(type ?? IConfigPassword.complexPassword, {
        ...data,
        attrs: {
          ...attribute,
          [attributeTypeArr[0]]: {
            ...attribute?.[attributeTypeArr[0]],
            value: value,
          },
        },
      });
    }
  };

  const onToggleSelected = (attrSelect: IAttrs, attrType: string) => () => {
    if (attrSelect.type === 'Boolean') {
      attrSelect.value = attrSelect.value === 'true' ? 'false' : 'true';
      setAttribute({...attribute, [attrType]: attrSelect});
    }
  };

  const renderByType = () => {
    switch (type) {
      case IConfigPassword.complexPassword:
        return (
          <ViewCM style={styles.content}>
            <CounterItem
              label={t('eContract.GS.passwordConfig.minimumLengthTitle')}
              attention={t('eContract.GS.passwordConfig.minimumLengthCharacters', {
                min: counterArr[0].min,
                max: counterArr[0].max,
              })}
              value={value}
              onPressMinus={decrease}
              onPressPlus={increase}
              onPressSetData={setCountData}
              min={counterArr[0].min}
              max={counterArr[0].max}
            />
            <ItemChoose
              data={attribute?.['digit']}
              onToggleSelected={onToggleSelected(attribute?.['digit'], 'digit')}
              label={t('eContract.GS.passwordConfig.atleastDigit')}
            />
            <ItemChoose
              data={attribute?.['lowercase-char']}
              onToggleSelected={onToggleSelected(
                attribute?.['lowercase-char'],
                'lowercase-char',
              )}
              label={t('eContract.GS.passwordConfig.atleastLowercase')}
            />
            <ItemChoose
              data={attribute?.['uppercase-char']}
              onToggleSelected={onToggleSelected(
                attribute?.['uppercase-char'],
                'uppercase-char',
              )}
              label={t('eContract.GS.passwordConfig.atleastUppercase')}
            />
            <ItemChoose
              data={attribute?.['special-char']}
              onToggleSelected={onToggleSelected(
                attribute?.['special-char'],
                'special-char',
              )}
              label={t('eContract.GS.passwordConfig.atleastSpecialCharacter')}
            />
          </ViewCM>
        );
      case IConfigPassword.timeResetExpired:
        return (
          <ViewCM style={styles.content}>
            <CounterItem
              label={t('eContract.GS.passwordConfig.notifyAfterDayLabel')}
              attention={t('eContract.GS.passwordConfig.notifyAterDayAttention', {
                min: counterArr[0].min,
                max: counterArr[0].max,
              })}
              value={value}
              onPressMinus={decrease}
              onPressPlus={increase}
              onPressSetData={setCountData}
              min={counterArr[0].min}
              max={counterArr[0].max}
            />
            <CounterItem
              label={t('eContract.GS.passwordConfig.resetAfterDayLabel')}
              attention={t('eContract.GS.passwordConfig.resetAfterDayAttention', {
                min: counterArr?.[1]?.min,
                max: counterArr?.[1]?.max,
              })}
              value={valueSecond}
              onPressMinus={decreaseSecond}
              onPressPlus={increaseSecond}
              onPressSetData={setCountDataSecond}
              min={counterArr?.[1]?.min}
              max={counterArr?.[1]?.max}
            />
          </ViewCM>
        );
      case IConfigPassword.checkPasswordDuplicate:
        return (
          <CounterItem
            label={t('eContract.GS.passwordConfig.duplicatePasswordLabel')}
            attention={t('eContract.GS.passwordConfig.duplicatePasswordAttention', {
              min: counterArr[0].min,
              max: counterArr[0].max,
            })}
            value={value}
            onPressMinus={decrease}
            onPressPlus={increase}
            onPressSetData={setCountData}
            min={counterArr[0].min}
            max={counterArr[0].max}
          />
        );
      case IConfigPassword.lockingAccountWrongPassword:
        return (
          <CounterItem
            label={t('eContract.GS.passwordConfig.lockAccountLabel')}
            attention={t('eContract.GS.passwordConfig.lockAccountAttention', {
              min: counterArr[0].min,
              max: counterArr[0].max,
            })}
            value={value}
            onPressMinus={decrease}
            onPressPlus={increase}
            onPressSetData={setCountData}
            min={counterArr[0].min}
            max={counterArr[0].max}
          />
        );
      default:
        return null;
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <ViewCM style={styles.ctnContainer}>
          <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
          <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <ViewCM style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>{t('eContract.GS.config')}</TextCM>
              <ViewCM />
            </ViewCM>
            <ViewCM style={styles.viewBody}>
              <TextCM>
                {t(
                  LIST_CONFIG_PASSWORD.find(i => i.type === type)?.label ?? '',
                )}
              </TextCM>
              {renderByType()}
              <ButtonCM label={t('eContract.CM.TxtSave')} onPress={handleOnsubmit} />
            </ViewCM>
          </ViewCM>
        </ViewCM>
      </KeyboardAvoidingView>
    </Modal>
  );
};

interface ItemChooseProps {
  data: IAttrs;
  onToggleSelected: () => void;
  label: string;
}

const ItemChoose = ({data, onToggleSelected, label}: ItemChooseProps) => {
  return (
    <TouchableOpacity style={styles.viewItem} onPress={onToggleSelected}>
      {data?.value === 'true' ? (
        <IcCheckboxSelect width={SizeDP(24)} height={SizeDP(24)} />
      ) : (
        <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
      )}
      <TextCM>{label}</TextCM>
    </TouchableOpacity>
  );
};

export default ModalConfigPassword;
