import {debounce, isEmpty} from 'lodash';
import {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {RefreshControl, ScrollView} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from '../styles';
import ImageSignatureItem from './components/ImageSignatureItem';
import InputSearch from './components/InputSearch';
import ModalAddImageSignature from './components/ModalAddImageSignature';
import {useAppDispatch} from '../../../hook/useRedux';
import {IImageSignature} from '../../../services/interface';
import ButtonCM from '../../../components/Button';
import TextCM from '../../../components/Text';
import {View as ViewCM} from 'react-native';
import { useAccountServices } from '../../../hook/apiHook/useApi';

export type ModalAddType = 'ADD' | 'EDIT';

const ImageSignature = () => {
  const dispatch = useAppDispatch();
  const {t} = useTranslation();
  // const {isReloadingSign} = useAppSelector(state => state.account);

  const [listData, setListData] = useState<IImageSignature[]>([]);
  const [searchText, setSearchText] = useState('');
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const [modalAddImageSignature, setModalAddImageSignature] = useState(false);
  const [typeModalAdd, setTypeModalAdd] = useState<ModalAddType>('ADD');

  const accountServices = useAccountServices();

  const toggleModalAdd = (type: ModalAddType = 'ADD') => {
    setTypeModalAdd(type);
    setModalAddImageSignature(!modalAddImageSignature);
  };

  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    getListData(debouncedSearchText);
  }, [debouncedSearchText.trim()]);

  const getListData = async (keyWord = '') => {
    try {
      const params = {
        name: keyWord,
      };
      const res = await accountServices.listImageSignature(params);
      const lsStar = res.filter(i => i.star);
      const lsUnStar = res.filter(i => !i.star);
      setListData([...lsStar, ...lsUnStar]);
      // dispatch(accountServices.setIsReloadingSign(!isReloadingSign));
    } catch (error) {
    } finally {
      setIsRefreshing(false);
    }
  };

  const renderItem = (item: IImageSignature) => {
    return (
      <ImageSignatureItem key={item.id} data={item} onSuccess={onSuccess} />
    );
  };

  const onRefresh = () => {
    setIsRefreshing(true);
    getListData(debouncedSearchText);
  };

  const onSuccess = () => {
    getListData(debouncedSearchText);
  };

  return (
    <SafeAreaView style={styles.ctn} edges={['bottom']}>
      <InputSearch searchText={searchText} setSearchText={setSearchText} />
      <ScrollView
        style={styles.ctnView}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }>
        {isEmpty(listData) ? (
          <Nodata />
        ) : (
          <ViewCM>{listData.map(renderItem)}</ViewCM>
        )}

        {modalAddImageSignature && (
          <ModalAddImageSignature
            isVisible={modalAddImageSignature}
            onClose={() => toggleModalAdd()}
            type={typeModalAdd}
            onSuccess={onSuccess}
            isNew={isEmpty(listData)}
          />
        )}
      </ScrollView>
      <ViewCM style={styles.btnAdd}>
        <ButtonCM
          label={t('eContract.AC.addImageSignature')}
          onPress={() => toggleModalAdd()}
        />
      </ViewCM>
    </SafeAreaView>
  );
};

export default ImageSignature;

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('eContract.DC.TxtNoData')}</TextCM>;
};
