import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity, View} from 'react-native';
import styles from './styles';

import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {IcBlackLeftArrow} from '../../../../../../../assets/images';
import TextCM from '../../../../../../../components/Text';
import ButtonCM from '../../../../../../../components/Button';
import GroupListCheck from '../../../../../../../components/GroupListCheck';

type ModalTypeShareProp = {
  onClose: () => void;
  isVisible: boolean;
  data: any[];
  onSubmit: (item: any[]) => void;
  currentSelected: any[];
};

const ModalTypeShare = ({
  onClose,
  isVisible,
  data,
  onSubmit,
  currentSelected,
}: ModalTypeShareProp) => {
  const {t} = useTranslation();
  const [currentValue, setCurrentValue] = useState(currentSelected);
  const insets = useSafeAreaInsets();

  const hanndleOnpress = (item: any) => {
    if (currentValue.some(i => i.id === item.id)) {
      setCurrentValue(currentValue.filter(i => i.id !== item.id));
    } else {
      setCurrentValue([...currentValue, item]);
    }
  };

  const handleOnsubmit = () => {
    onSubmit(currentValue);
    onClose();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('eContract.DC.ShareDocument.typeShare')}
            </TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            <TextCM style={styles.txtLabel}>
              {t('eContract.DC.ShareDocument.chooseTypeShare')}
            </TextCM>
            <GroupListCheck
              data={data}
              onPressData={hanndleOnpress}
              currentValue={currentValue}
              scrollEnabled={true}
            />
            <ButtonCM label={t('eContract.CM.BtnConfirm')} onPress={handleOnsubmit} />
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModalTypeShare;
