import {isEmpty} from 'lodash';
import React from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, View} from 'react-native';
import styles from './styles';
import {IDocumentTemplate} from '../../../../../model/interface/envelope.interface';
import {DateUtils} from '../../../../../utils';
import {
  IconBluePublished,
  IconBlueUnpublished,
} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type Props = {
  isVisible: boolean;
  toggleModal: () => void;
  data: any;
  onUpdateSuccess: () => void;
};

const ModalConfirmUpdateValidity = ({
  isVisible,
  toggleModal,
  data,
  onUpdateSuccess,
}: Props) => {
  const {t} = useTranslation();
  const DocumentServices = useDocumentServices();
  const onPressUpdate = async () => {
    try {
      await DocumentServices.updateListDocumentTemplate(data);
      toggleModal();
      onUpdateSuccess();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    }
  };

  const renderItem = ({item}: {item: IDocumentTemplate}) => {
    const LIST = [
      {
        title: t('eContract.DC.DocumentTemplate.TxtEffectFrom'),
        value: DateUtils.convertDateToDDMMYYYY(item?.effDate),
      },
      {
        title: t('eContract.DC.DocumentTemplate.TxtEffectTo'),
        value: DateUtils.convertDateToDDMMYYYY(item?.expDate),
      },
    ];
    return (
      <View style={styles.viewItem}>
        <View style={styles.viewHeader}>
          {item.status === 'published' ? (
            <IconBlueUnpublished width={24} height={24} />
          ) : (
            <IconBluePublished width={24} height={24} />
          )}
          <TextCM
            style={{
              ...styles.txtName,
              color: item.status === 'published' ? '#070708' : '#667085',
            }}>
            {item.name}
          </TextCM>
        </View>
        <View style={styles.viewBody}>
          {LIST.map((item, index) => {
            return (
              <View key={item.title} style={styles.viewItemBody}>
                <TextCM style={styles.txtTitle}>{item.title}</TextCM>
                <TextCM style={styles.txtValue}>{item.value}</TextCM>
              </View>
            );
          })}
          <View style={styles.viewItemBody}>
            <View style={styles.viewName}>
              <TextCM style={styles.txtTitle}>{t('eContract.DC.TxtParties')}</TextCM>
            </View>
            <View style={styles.viewValueParties}>
              {!isEmpty(item?.parties) ? (
                item?.parties?.map((i: any) => {
                  return (
                    <TextCM style={styles.txtValue} key={i.id}>
                      {i.type !== 'individual'
                        ? i.name || '---'
                        : i.recipients?.[0]?.contact?.name}
                    </TextCM>
                  );
                })
              ) : (
                <TextCM style={styles.txtValue}>---</TextCM>
              )}
            </View>
          </View>
        </View>
      </View>
    );
  };

  const Content = () => {
    return (
      <View style={styles.content}>
        <View style={styles.viewDes}>
          <TextCM style={styles.txtDes}>
            {t('eContract.DC.DocumentTemplate.TxtDesConfirm')}
          </TextCM>
        </View>
        <View style={styles.body}>
          <FlatList
            data={data}
            keyExtractor={(item, index) => item.id}
            renderItem={renderItem}
            contentContainerStyle={{
              gap: 16,
            }}
          />
        </View>
        <ButtonCM onPress={onPressUpdate} label={t('eContract.DC.TxtUpdate')} />
      </View>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('eContract.DC.DocumentTemplate.TxtUpdateInfo')}
        renderContent={<Content />}
        onClose={toggleModal}
        isVisible={isVisible}
      />
    </>
  );
};

export default ModalConfirmUpdateValidity;
