import { IHistoryConfigLogin } from "../../../../../services/interface";

const findDifferences = (cdc: any) => {
  const result: any = {
    value: {},
    previousValue: {},
  };

  // Check for differences in name, type, active, and attribute
  ['name', 'type', 'active'].forEach(prop => {
    if (cdc.value[prop] !== cdc.previousValue[prop]) {
      result.value[prop] = cdc.value[prop];
      result.previousValue[prop] = cdc.previousValue[prop];
    }
  });

  // Check for differences in attribute object
  const valueAttributes = cdc.value?.attribute;
  const previousValueAttributes = cdc?.previousValue?.attribute;
  const attributeDifferencesValue: any = {};
  const attributeDifferencesPreviousValue: any = {};

  if (valueAttributes && previousValueAttributes) {
    Object.keys(valueAttributes).forEach(key => {
      if (valueAttributes[key] !== previousValueAttributes[key]) {
        attributeDifferencesValue[key] = valueAttributes[key];
        attributeDifferencesPreviousValue[key] = previousValueAttributes[key];
      }
    });
  }

  if (Object.keys(attributeDifferencesValue).length > 0) {
    result.value['attribute'] = attributeDifferencesValue;
    result.previousValue['attribute'] = attributeDifferencesPreviousValue;
  }

  return result;
};

export const mapData = (data: IHistoryConfigLogin) => {
  if (!data?.cdc) return {};
  if (!data?.cdc?.previousValue) {
    return {
      value: data?.cdc?.value,
      previousValue: {},
    };
  }
  return findDifferences(data?.cdc);
};

export const convertObjectToArray = (obj: any) => {
  return Object.keys(obj).map(key => ({
    key: key,
    value: obj[key],
  }));
};
