import {useNavigation} from '@react-navigation/native';
import {isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Platform, TouchableOpacity, View} from 'react-native';
import DocumentPicker from 'react-native-document-picker';
import {
  checkIsEmail,
  checkIsPhoneNumber,
  convertDataExcel,
  convertDataPartiesExcel,
  createDownloadFileExcel,
  getDataFromExcelFile2,
  getFileName,
  listNameColumnExcel,
  mapDataWithColumns,
  sortDataError,
} from './helper';
import styles from './styles';
import {DateUtils} from '../../../../../utils';
import Toast from 'react-native-toast-message';
import TextCM from '../../../../../components/Text';
import {
  IconBlueFileUpload,
  IconGreenExcel,
  IconRedFileError,
} from '../../../../../assets/images';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import {NavigationName} from '../../../../../constants';
import useCreateBatchStore from '../../../store/createBatchStore';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type Props = {
  isVisible: boolean;
  toggleModal: () => void;
};

const ModalCreateBatch = ({isVisible, toggleModal}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();

  const {dataTemplate, dataExcel, setDataExcel} = useCreateBatchStore();

  const [file, setFile] = useState<any>();
  const [dataError, setDataError] = useState<string[]>([]);

  const [listRequiredFields, setListRequiredFields] = useState<any[]>([]);

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    checkDataFile();
  }, [file]);

  useEffect(() => {
    getListDocTypes();
  }, [dataTemplate]);

  const getListFieldsRequester = () => {
    return dataTemplate?.requester.fields
      .filter(item => {
        if (
          item.type === 'text' ||
          (item.type === 'currency' && isEmpty(item.recipientId)) ||
          (item.type === 'information' && isEmpty(item.recipientId))
        ) {
          const valid =
            item.validators?.find(i => i.type === 'required')?.expression ===
            'true';

          return valid && isEmpty(item.recipientId);
        }
        return false;
      })
      ?.map(item => ({
        id: item.id,
        name: item.name,
        type: item.type,
      }));
  };

  const getListDocTypes = async () => {
    if (!dataTemplate?.docTypeCode) return;
    const data = await DocumentServices.getListDocTypes(
      dataTemplate?.docTypeCode,
    );

    const listDocTypesRequired = data
      .filter((item: any) => item.required && item.id !== 'envSubmittedFrom')
      .map((item: any) => ({
        id: item.id,
        name: item.name,
        type: item.type,
      }));
    setListRequiredFields([
      ...listDocTypesRequired,
      ...(getListFieldsRequester() || []),
    ]);
  };

  const checkDataFile = async () => {
    if (isEmpty(file)) return;
    setDataError([]);

    try {
      const dataTemp = getDataTemplatesExcel();
      const numberOfKeys = Object.keys(dataTemp).length;
      const lsNameColumnTempExcel = listNameColumnExcel.slice(0, numberOfKeys);

      const data = await getDataFromExcelFile2(
        Platform.OS === 'ios'
          ? decodeURIComponent(file.uri.replace('file://', ''))
          : file.uri,
        lsNameColumnTempExcel,
      );
      setDataExcel(data);

      if (isEmpty(data)) {
        setDataError([t('eContract.DC.CreateBatch.TxtNumberNotMatch')]);
        return;
      }
      const numberOfKeysDataCurrentFile = Object.keys(data[0]).length;
      if (numberOfKeysDataCurrentFile !== numberOfKeys) {
        setDataError([t('eContract.DC.CreateBatch.TxtNumberNotMatch')]);
        return;
      }
      const dataMap = mapDataWithColumns(dataTemp, lsNameColumnTempExcel);
      checkMatchData(data, dataMap);
    } catch (error) {
      console.log('error: ', error);
    }
  };

  const checkMatchData = async (
    data: Record<string, any>[],
    dataTemp: Record<string, any>,
  ) => {
    const lsValue = data.slice(1);

    const errors: string[] = [];

    Object.keys(dataTemp).forEach((key: any, index) => {
      if (data[0][key] !== dataTemp[key]) {
        errors.push(
          t('eContract.DC.CreateBatch.TxtRowColumnError', {
            row: 1,
            column: index + 1,
          }),
        );
      }
    });
    const lsParties = Object.values(dataTemp).filter(i => {
      return [
        t('eContract.DC.CreateBatch.TxtOrganization').toLowerCase(),
        t('eContract.DC.CreateBatch.TxtIndividual').toLowerCase(),
        t('eContract.DC.TxtUserSigner').toLowerCase(),
      ].some(item => i.toLowerCase().includes(item));
    });

    lsValue.forEach((value: any, index) => {
      /// check không nhập thông tin các trường bắt buộc

      // Tạo một mảng các tên cần giữ lại từ data
      const namesToKeep = listRequiredFields.map(item => item.name);
      namesToKeep.push(...lsParties);
      // Tạo một đối tượng để ánh xạ từ name sang type
      const nameToType = Object.fromEntries(
        listRequiredFields.map(item => [item.name, item.type, item.name]),
      );
      // Tạo một mảng các đối tượng với định dạng [{key: 'A', type: 'String'}]
      const resultCheck = Object.entries(dataTemp)
        .filter(([key, value]) => namesToKeep.includes(value))
        .map(([key, value]) => ({key, name: value, type: nameToType[value]}));

      resultCheck.forEach(field => {
        const valueField = value[field.key];
        if (!valueField) {
          errors.push(
            t('eContract.DC.CreateBatch.TxtRowColumnRequired', {
              row: index + 2,
              column: Object.keys(value).indexOf(field.key) + 1,
            }),
          );
        }
      });

      // check nhập thông tin không đúng định dạnh

      Object.keys(dataTemp).forEach(key => {
        const fieldName: string = dataTemp[key];
        const fieldValue = value[key];

        // Find the corresponding field in listType
        const fieldType = dataTemplate?.header.fields.find(
          item => item.name === fieldName,
        )?.type;

        // Check if the field type is Date
        if (fieldType === 'Date' && !!fieldValue) {
          if (!DateUtils.isValidDateDDMMYYYY(fieldValue)) {
            errors.push(
              t('eContract.DC.CreateBatch.TxtErrorFormatEmailDate', {
                row: index + 2,
                column: Object.keys(value).indexOf(key) + 1,
              }),
            );
          }
        }
        if (fieldName.toUpperCase().includes('SĐT') && !isEmpty(fieldValue)) {
          if (!checkIsPhoneNumber(fieldValue)) {
            errors.push(
              t('eContract.DC.CreateBatch.TxtErrorFormatSDT', {
                row: index + 2,
                column: Object.keys(value).indexOf(key) + 1,
              }),
            );
          }
        }
        if (fieldName.toUpperCase().includes('EMAIL') && !isEmpty(fieldValue)) {
          if (!checkIsEmail(fieldValue)) {
            errors.push(
              t('eContract.DC.CreateBatch.TxtErrorFormatEmail', {
                row: index + 2,
                column: Object.keys(value).indexOf(key) + 1,
              }),
            );
          }
        }
      });
    });

    setDataError(prev => [...prev, ...errors]);
  };

  const onPressCreate = () => {
    toggleModal();
    navigation.navigate(NavigationName.CreateBatchScreen);
  };

  const onPicFile = async () => {
    // TODO: Implement upload file
    try {
      const res = await DocumentPicker.pick({
        type: [DocumentPicker.types.xls, DocumentPicker.types.xlsx],
      });
      const data: any = res?.[0];
      if (data?.size > 10000000) {
        Toast.show({
          type: 'error',
          text1: t('eContract.DC.Messages.TxtMaxSizeFile'),
        });
      } else {
        setFile(res?.[0]);
      }
    } catch (err) {
      if (DocumentPicker.isCancel(err)) {
        console.log('User cancelled the picker');
      } else {
        console.error(err);
      }
    }
  };

  const getDataTemplatesExcel = () => {
    var fields: any =
      dataTemplate?.header?.fields
        .filter(i => i.id !== 'envSubmittedFrom')
        .map(item => {
          if (item.type === 'Date') {
            return {
              ...item,
              value: DateUtils.convertDateToDDMMYYYY(new Date()),
            };
          }
          return item;
        }) || [];
    fields = convertDataExcel(fields);
    const parties = convertDataPartiesExcel(dataTemplate?.parties || []);

    var fieldsRequester: any = dataTemplate?.requester?.fields.filter(item => {
      if (
        (item.type === 'information' && isEmpty(item.recipientId)) ||
        item.type === 'text' ||
        (item.type === 'currency' && isEmpty(item.recipientId))
      ) {
        return true;
      }
      return false;
    });
    fieldsRequester = convertDataExcel(fieldsRequester);

    return {...fields, ...fieldsRequester, ...parties};
  };

  const onDownloadTemplate = () => {
    const dataExcel = getDataTemplatesExcel();
    // Tạo một đối tượng mới với các giá trị được cắt lại tối đa 32676 ký tự
    const truncatedDataExcel = Object.fromEntries(
      Object.entries(dataExcel).map(([key, value]: any) => [
        key,
        value?.toString()?.slice(0, 32676),
      ]),
    );
    createDownloadFileExcel(
      [truncatedDataExcel],
      dataTemplate?.name || '',
      onDownSuccess,
    );
  };

  const onDownSuccess = (filePath?: string) => {
    const newPath = Platform.OS === 'ios' ? 'Documents' : 'Download';
    const fileName = getFileName(filePath);
    Toast.show({
      type: 'success',
      text1: t('eContract.DC.CreateBatch.TxtDownLoadFileTemplateSuccess', {
        name: `“${fileName || ''}”`,
        path: `“${newPath}”`,
      }),
    });
  };

  const renderItemError = (item: string) => {
    return (
      <TextCM key={item} style={styles.txtItemError}>
        {item}
      </TextCM>
    );
  };

  const Content = () => {
    return (
      <View style={styles.content}>
        <View style={styles.body}>
          <TextCM style={styles.txtTitle}>
            {t('eContract.DC.CreateBatch.TxtLabel')}
          </TextCM>
          {isEmpty(file) ? (
            <View style={styles.viewUpload}>
              <IconBlueFileUpload width={30} height={40} />
              <TextCM style={styles.txtLabelUpload}>
                {t('eContract.DC.CreateBatch.TxtDragAndDropYourFile')}
              </TextCM>
              <TextCM style={styles.txtSupport}>
                {t('eContract.DC.CreateBatch.TxtSupportedFormats')}
              </TextCM>
              <ButtonCM
                label={t('eContract.DC.CreateBatch.TxtUploadFile')}
                style={styles.btnUploadFile}
                onPress={onPicFile}
              />
            </View>
          ) : (
            <View
              style={[
                styles.viewUploadOK,
                !isEmpty(dataError) && styles.viewUploadError,
              ]}>
              {isEmpty(dataError) ? (
                <IconGreenExcel width={30} height={40} />
              ) : (
                <IconRedFileError width={30} height={40} />
              )}
              <TextCM style={styles.txtLabelUpload}>
                {file.name.replace(/\.(xlsx|xls)$/, '')}
              </TextCM>
              {isEmpty(dataError) ? (
                <TextCM style={styles.txtSupport}>
                  {t('eContract.DC.CreateBatch.TxtValidDataTotal')}
                  <TextCM style={styles.txtLine}>
                    {' '}
                    {dataExcel.length - 1 < 1 ? 1 : dataExcel.length - 1}{' '}
                    {t('eContract.DC.CreateBatch.TxtLine')}
                  </TextCM>
                </TextCM>
              ) : (
                <TextCM style={styles.txtError}>
                  {t('eContract.DC.CreateBatch.TxtDataError')}
                  <TextCM style={styles.txtNumberError}>
                    {' '}
                    {dataError.length} {t('eContract.DC.CreateBatch.TxtError')}
                  </TextCM>
                </TextCM>
              )}
              {!isEmpty(dataError) && (
                <View>{sortDataError(dataError).map(renderItemError)}</View>
              )}
              <ButtonCM
                type="white"
                label={t('eContract.DC.CreateBatch.TxtUploadDifferentVersion')}
                style={styles.btnUploadFile}
                onPress={onPicFile}
              />
            </View>
          )}
          <View style={styles.viewNote}>
            <TextCM style={styles.txtNoTemplate}>
              {t('eContract.DC.CreateBatch.TxtNoTemplateAvailable')}
              <TextCM style={styles.txtName}>
                {' '}
                {`“${dataTemplate?.name}”`}?
              </TextCM>
            </TextCM>
            <View style={styles.viewDownTemplate}>
              <TextCM style={styles.txtNoTemplate}>
                {t('eContract.DC.CreateBatch.TxtDownloadTemplateDocument')}
              </TextCM>
              <TouchableOpacity
                style={styles.btnDownTemplate}
                onPress={onDownloadTemplate}>
                <TextCM style={styles.txtHere}>
                  {t('eContract.DC.CreateBatch.TxtHere')}
                </TextCM>
              </TouchableOpacity>
            </View>
          </View>
        </View>
        <View style={styles.footer}>
          <ButtonCM
            label={t('eContract.CM.BtnContinue')}
            onPress={onPressCreate}
            disabled={isEmpty(file) || !isEmpty(dataError)}
          />
        </View>
      </View>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('eContract.DC.TxtCreateBatches')}
        renderContent={<Content />}
        onClose={toggleModal}
        isVisible={isVisible}
      />
    </>
  );
};

export default ModalCreateBatch;
