import React from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, ScrollView, TouchableOpacity} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';

import {getObjectDiff, mappingTypeToLabel} from './helper';
import { IHistoryPassword, IPasswordConfig } from '../../../../../services/interface';
import { View as ViewCM } from 'react-native';
import { IcBlackLeftArrow, IcCheckbox, IconGreyCheckSelected } from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import { SizeDP } from '../../../../../constants/Size';

type ModalDetailHistoryPasswordProp = {
  onClose: () => void;
  isVisible: boolean;
  type: string;
  data: IHistoryPassword;
};

const ModalDetailHistoryPassword = ({
  onClose,
  isVisible,
  data,
}: ModalDetailHistoryPasswordProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();

  const renderHistory = () => {
    const isDiffStatus = getObjectDiff(
      data.cdc.previousValue,
      data.cdc.value,
    ).includes('status');

    const isDiffDescription = getObjectDiff(
      data.cdc.previousValue?.attrs,
      data.cdc.value?.attrs,
    );

    return (
      <ScrollView style={{flex: 1}} showsVerticalScrollIndicator={false}>
        <ViewCM style={styles.diffCtn}>
          <DiffItem
            label={t('eContract.GS.history.oldInfo')}
            isDiffStatus={isDiffStatus}
            listTypeDetails={isDiffDescription}
            data={data?.cdc?.previousValue ?? undefined}
          />
          <DiffItem
            label={t('eContract.GS.history.newInfo')}
            isDiffStatus={isDiffStatus}
            listTypeDetails={isDiffDescription}
            data={data.cdc.value}
          />
        </ViewCM>
      </ScrollView>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('eContract.GS.history.detailHistory')}
            </TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.viewBody}>
            {renderHistory()}
            <ButtonCM onPress={onClose} label={t('eContract.CM.BtnClose')} />
          </ViewCM>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

const DiffItem = ({
  listTypeDetails,
  data,
  isDiffStatus,
  label,
}: {
  listTypeDetails: string[];
  data?: IPasswordConfig;
  label: string;
  isDiffStatus: boolean;
}) => {
  const {t} = useTranslation();

  return (
    <ViewCM style={styles.ctnInfo}>
      <TextCM style={styles.txtLabel}>{label}</TextCM>
      <ViewCM style={styles.diffInfoCtn}>
        {isDiffStatus && (
          <ViewCM style={styles.item}>
            <TextCM style={styles.txt400small}>{t('eContract.GS.autoConfig.status')}</TextCM>
            <TextCM>
              {data?.status
                ? t('eContract.GS.history.active')
                : t('eContract.GS.history.nonActive')}
            </TextCM>
          </ViewCM>
        )}
        {listTypeDetails.length > 0 && (
          <ViewCM>
            <TextCM style={styles.txt400small}>{t('eContract.GS.configSecurityLogin.TxtProperties')}</TextCM>
            <ViewCM style={styles.diffDetailCtn}>
              {listTypeDetails.map((item, index) => {
                const valueItem = data?.attrs?.[item];
                return (
                  <ViewCM key={index} style={styles.item}>
                    <TextCM style={styles.txtXsmall}>
                      {t(mappingTypeToLabel(item, data?.configType ?? ''))}
                    </TextCM>
                    <ViewCM style={styles.valueCtn}>
                      {valueItem?.type === 'Boolean' && (
                        <ViewCM>
                          {valueItem?.value === 'true' ? (
                            <IconGreyCheckSelected
                              width={SizeDP(24)}
                              height={SizeDP(24)}
                            />
                          ) : (
                            <IcCheckbox
                              width={SizeDP(24)}
                              height={SizeDP(24)}
                            />
                          )}
                        </ViewCM>
                      )}
                      {valueItem?.type !== 'Boolean' && (
                        <TextCM style={styles.txtXsmallValue}>
                          {valueItem?.value}
                        </TextCM>
                      )}
                    </ViewCM>
                  </ViewCM>
                );
              })}
            </ViewCM>
          </ViewCM>
        )}
      </ViewCM>
    </ViewCM>
  );
};

export default ModalDetailHistoryPassword;
