import {BASE_URL} from './httpClient';

export const createHomeServices = (fetchRequest: any) => ({
  async fetchFindById(orgIn: string) {
    const endPoint = '/services/uaa/api/user-org-reports/findById';
    try {
      const response = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        body: JSON.stringify({id: orgIn}),
      });
      return Promise.resolve(response.data);
    } catch (error) {
      return Promise.reject(error);
    }
  },

  async fetchTransferData(owner: string) {
    const endPoint = '/services/notify/api/notifications/transferdata';
    try {
      const response = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        body: JSON.stringify({owner}),
      });
      return Promise.resolve(response.data);
    } catch (error) {
      return Promise.reject(error);
    }
  },

  async fetchInfo(orgIn: string, owner: string) {
    const endPoint = '/services/envelope/api/dashboardsummaries/info';
    try {
      const response = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        body: JSON.stringify({orgIn, owner}),
      });
      return Promise.resolve(response.data);
    } catch (error) {
      return Promise.reject(error);
    }
  },
});
