import React, {useState} from 'react';
import {Controller, useFormContext} from 'react-hook-form';
import {View} from 'react-native';
import {EyesIcon, EyesIconOpen} from '../../../../../../../assets/images';
import TextFieldCM from '../../../../../../../components/TextField';

type Props = {
  controlName: string;
  label: string;
  isRequired?: boolean;
  maxLength?: number;
};

const YupTextField = ({controlName, label, isRequired, maxLength}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  const [isSecureText, setIsSecureText] = useState<boolean>(true);

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextFieldCM
              label={label}
              placeholder={label}
              isRequired={isRequired}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              secureTextEntry={isSecureText}
              onIconPress={() => setIsSecureText(!isSecureText)}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={
                isSecureText ? (
                  <EyesIcon width={24} height={24} />
                ) : (
                  <EyesIconOpen width={24} height={24} />
                )
              }
            />
          );
        }}
      />
    </View>
  );
};

export default YupTextField;
