import {useRoute} from '@react-navigation/native';
import React, {useMemo} from 'react';
import {useTranslation} from 'react-i18next';
import {View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {
  NavigationState,
  SceneMap,
  SceneRendererProps,
  TabBar,
  TabView,
} from 'react-native-tab-view';
import styles from './styles';
import HistoryScreen from './tabScreens/historyScreen';
import PermissionScreen from './tabScreens/permissionScreen';
import ShareScreen from './tabScreens/shareScreen';
import TextCM from '../../../components/Text';
import {IDocument} from '../../../model/interface/envelope.interface';
import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import HeaderCM from '../../../components/Header/HeaderCM';
import {useDocumentStore} from '../../../navigation/SideMenu/store/app-store';

const renderTabBar = (
  props: SceneRendererProps & {
    navigationState: NavigationState<{
      key: string;
      title: string;
    }>;
  },
) => (
  <TabBar
    {...props}
    indicatorStyle={styles.indicatorStyle}
    indicatorContainerStyle={styles.indicatorContainerStyle}
    style={styles.tabBarStyle}
    tabStyle={styles.tabStyle}
    activeColor="#0673C6"
    inactiveColor="#667085"
    contentContainerStyle={styles.contentContainerStyle}
    renderLabel={({route, focused, color}) => (
      <View
        style={{
          flex: 1,
          alignItems: 'center',
          justifyContent: 'center',
        }}>
        <TextCM style={(styles.txtTabText, {color})}>{route.title}</TextCM>
      </View>
    )}
  />
);

const DocumentShare = () => {
  const route = useRoute<any>();
  const dataRoute: IDocument = route.params.data;
  const [index, setIndex] = React.useState(0);
  const {t} = useTranslation();
  const currentFocused = useDocumentStore(state => state.currentFocused);

  const [routes] = React.useState(
    currentFocused === ItemType.MyDocumentTemplate
      ? [
          {key: 'permission', title: t('eContract.DC.TxtShare')},
          {key: 'history', title: t('eContract.HM.TxtHistory')},
        ]
      : [
          {key: 'share', title: t('eContract.DC.TxtShare')},
          {key: 'permission', title: t('eContract.DC.ShareDocument.allowPermission')},
          {key: 'history', title: t('eContract.HM.TxtHistory')},
        ],
  );
  const renderScene = useMemo(
    () =>
      SceneMap(
        currentFocused === ItemType.MyDocumentTemplate
          ? {
              permission: () => <PermissionScreen data={dataRoute} />,
              history: () => <HistoryScreen data={dataRoute} />,
            }
          : {
              share: () => <ShareScreen data={dataRoute} />,
              permission: () => <PermissionScreen data={dataRoute} />,
              history: () => <HistoryScreen data={dataRoute} />,
            },
      ),
    [dataRoute],
  );

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM
        title={
          currentFocused === ItemType.MyDocumentTemplate
            ? t('eContract.DC.TxtShareDocumentTemplates')
            : t('eContract.DC.ShareDocument.label')
        }
      />
      <View style={{flex: 1}}>
        <TabView
          renderTabBar={renderTabBar}
          navigationState={{index, routes}}
          renderScene={renderScene}
          onIndexChange={setIndex}
        />
      </View>
    </SafeAreaView>
  );
};

export default DocumentShare;
