import {TouchableWithoutFeedback, View} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {FC} from 'react';
import TextCM from '../../../../components/Text';

export enum TypeTabs {
  DRAW,
  DEVICES,
}
type Props = {
  onChangeTabs: (value: TypeTabs) => void;
  selected: TypeTabs;
};

const TabsComponent: FC<Props> = ({
  selected = TypeTabs.DEVICES,
  onChangeTabs,
}) => {
  const {t} = useTranslation();
  return (
    <View style={styles.ctnMain}>
      <TouchableWithoutFeedback
        onPress={() => onChangeTabs(TypeTabs.DEVICES)}
        style={styles.centerBox}>
        <TextCM
          style={[
            styles.textBtn,
            selected === TypeTabs.DEVICES && styles.textBtnSelect,
          ]}>
          {t('eContract.AC.tabs.devices')}
        </TextCM>
      </TouchableWithoutFeedback>
      <TouchableWithoutFeedback
        onPress={() => onChangeTabs(TypeTabs.DRAW)}
        style={styles.centerBox}>
        <TextCM
          style={[
            styles.textBtn,
            selected === TypeTabs.DRAW && styles.textBtnSelect,
          ]}>
          {t('eContract.AC.tabs.draw')}
        </TextCM>
      </TouchableWithoutFeedback>
    </View>
  );
};

export default TabsComponent;
