import {some} from 'lodash';
import {
  IOrg,
  IDocument,
  IGroup,
  IExternalShared,
} from '../../../../../../../model/interface/envelope.interface';
import {IAccount} from '../../../../../../../services/interface';

export interface IAclInternalListNew {
  id: null | string;
  resourceId: string;
  resourceName: string;
  resourceType: string;
  sharedType: string;
  personal: string;
  group: number;
  password: null | string;
  perm: string;
  fromDate: string;
  toDate: null | string;
  custId: number;
  orgIn: string;
  activityLogName: string;
}

export const handleListMemberCanPermit = ({
  organiztion,
  dataEnvelope,
  listUserInOrg = [],
  listGroupInOrg = [],
  listAllGroupAndPersonShareBelongtoEnvelop = [],
}: {
  organiztion: IOrg;
  dataEnvelope: IDocument;
  listUserInOrg: IAccount[];
  listGroupInOrg: IGroup[];
  listAllGroupAndPersonShareBelongtoEnvelop: IExternalShared[];
}) => {
  // list shared person và group
  const listShared = listAllGroupAndPersonShareBelongtoEnvelop.filter(item => {
    return item?.orgIn === organiztion.orgIn;
  });

  // list user chưa được share của tổ chức
  const listUserNotShared = listUserInOrg.filter(user => {
    return !some(listShared, ['group', user.id]);
  });

  const listUserNotSharedFormat = listUserNotShared.map(user => {
    return {
      id: null,
      resourceId: dataEnvelope.id,
      resourceName: dataEnvelope.name,
      resourceType: 'e',
      sharedType: 'p',
      personal: user?.login,
      group: user.id,
      password: null,
      perm: 'v_d',
      fromDate: new Date().toISOString(),
      toDate: null,
      custId: user.custId,
      orgIn: user.orgIn,
      activityLogName: user?.login,
    };
  });

  // list group chưa được share của tổ chức
  const listGroupNotShared = listGroupInOrg.filter(group => {
    return !some(listShared, ['group', group.id]);
  });

  const listGroupNotSharedFormat = listGroupNotShared.map(group => {
    return {
      id: null,
      resourceId: dataEnvelope.id,
      resourceName: dataEnvelope.name,
      resourceType: 'e',
      sharedType: 'g',
      personal: group.name,
      group: group.id,
      password: null,
      perm: 'v_d',
      fromDate: new Date().toISOString(),
      toDate: null,
      custId: group.custId,
      orgIn: group.orgIn,
      activityLogName: group.name,
    };
  });

  return {
    listNotShared: [
      ...listGroupNotSharedFormat,
      ...listUserNotSharedFormat,
    ] as IAclInternalListNew[],
    listShared: listShared,
  };
};
