import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';

export const RELATED_CHOOSE = [
  {id: 'top', label: 'eContract.DC.DocumentRelate.topDocument'},
  {id: 'bottom', label: 'eContract.DC.DocumentRelate.belowDocument'},
];
export enum IRelatedDocument {
  myDocument = 'myDocument',
  decentralizationGroup = 'decentralizationGroup',
  decentralizationDirect = 'decentralizationDirect',
}

export const getPathRelated = ({
  type,
  tabKey,
  owner,
}: {
  type: ItemType;
  tabKey: IRelatedDocument;
  owner: string;
}) => {
  switch (tabKey) {
    case IRelatedDocument.decentralizationGroup:
      return {
        path: 'completed',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            owner: null,
          },
        },
      };

    case IRelatedDocument.decentralizationDirect:
      return {
        path: 'completed',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            owner: null,
          },
        },
      };

    default:
      return {
        path: 'completed',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            owner,
          },
        },
      };
      break;
  }
};

export const getAclValue = (
  tabKey: IRelatedDocument,
  groups: any[],
  owner: string,
) => {
  switch (tabKey) {
    case IRelatedDocument.decentralizationGroup:
      return {
        resourceId: null,
        resourceType: 'e',
        sharedType: 'g',
        personal: null,
        group: groups,
        perm: null,
        custId: null,
      };
      break;
    case IRelatedDocument.decentralizationDirect:
      return {
        resourceId: null,
        resourceType: 'e',
        sharedType: 'p',
        personal: owner,
        group: null,
        perm: null,
        custId: null,
      };
    default:
      return undefined;
      break;
  }
};
