import styles from './styles';
import {FC} from 'react';
import {TouchableOpacity, View} from 'react-native';
import {useTranslation} from 'react-i18next';
import {ISearchResponse} from '../../../../../model/interface/notification.interface';
import TextCM from '../../../../../components/Text';
import {IconBlueCheck} from '../../../../../assets/images';
import React from 'react';

type Props = {
  data: ISearchResponse;
  onSelect: (item: ISearchResponse) => void;
  dataSelect: ISearchResponse;
  setListData: (list: any[]) => void;
  listData: any[];
  type?: 'trusted' | 'all' | 'trusted_people';
};

const CardIdtemInfo: FC<Props> = ({
  data,
  onSelect,
  dataSelect,
  setListData,
  listData,
  type = 'all',
}) => {
  const {t} = useTranslation();
  const handleSelect = () => {
    const filterData = listData?.map(item => {
      if (!item?.select && item?.id === data?.id) {
        return {
          ...item,
          select: true,
        };
      } else {
        return {
          ...item,
          select: false,
        };
      }
    });
    const dataSelect = filterData.find(item => item?.select === true);
    onSelect(dataSelect ?? {});
    setListData(filterData);
  };

  return (
    <TouchableOpacity
      onPress={handleSelect}
      style={[styles.ctnMain, (data as any)?.select && styles.bgSelect]}>
      <View style={styles.ctnHeader}>
        <TextCM
          style={[
            styles.textHeader,
            (data as any)?.select && styles.textHeaderSelect,
          ]}>
          {type === 'trusted_people' ? data.name : data?.personalName}
        </TextCM>
        {(data as any)?.select && <IconBlueCheck width={16} height={12} />}
      </View>
      <View style={styles.ctnBody}>
        {type === 'all' && (
          <>
            <View style={styles.ctnView}>
              <TextCM style={styles.textTitle}>
                {t('eContract.NT.TxtOrganization')}
              </TextCM>
              <TextCM numberOfLines={1} style={styles.textDes}>
                {data?.orgName}
              </TextCM>
            </View>
            <View style={styles.ctnView}>
              <TextCM style={styles.textTitle}>{t('eContract.NT.postion')}</TextCM>
              <TextCM numberOfLines={1} style={styles.textDes}>
                {data?.position ?? '---'}
              </TextCM>
            </View>
          </>
        )}
        <View style={styles.ctnView}>
          <TextCM style={styles.textTitle}>Email</TextCM>
          <TextCM numberOfLines={1} style={styles.textDes}>
            {data?.email}
          </TextCM>
        </View>
        <View style={styles.ctnView}>
          <TextCM style={styles.textTitle}>{t('eContract.NT.TxtPhone')}</TextCM>
          <TextCM numberOfLines={1} style={styles.textDes}>
            {type === 'all' || type === 'trusted_people'
              ? data?.phone
              : data?.telephoneNumber}
          </TextCM>
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default CardIdtemInfo;
